    double dz = points[i].z - searchPoint.z;
    double dist = dx * dx + dy * dy + dz * dz;

    if (maxHeap.size() < k) {
        maxHeap.push({dist, i});
    } else if (dist < maxHeap.top().first) {
        maxHeap.pop();
        maxHeap.push({dist, i});
    }
}

result.resize(maxHeap.size());
